"use strict";
import { CurrencyAmount, Price } from "@uniswap/sdk-core";
import { Pair } from "@uniswap/v2-sdk";
import { useEffect, useState } from "react";
import { PositionField } from "types/position";
import { useQuery } from "@tanstack/react-query";
import { getAbstractSubgraphs } from "uniswap/src/constants/abstractContracts";
function parseReserveToRaw(reserve, decimals) {
  if (reserve.includes("e") || reserve.includes("E")) {
    try {
      const num = parseFloat(reserve);
      if (!isFinite(num) || num < 0) return "0";
      const fixedStr = num.toFixed(decimals);
      return parseReserveToRaw(fixedStr, decimals);
    } catch {
      return "0";
    }
  }
  const parts = reserve.split(".");
  const wholePart = parts[0] || "0";
  const fractionalPart = parts[1] || "";
  const fractionalDigits = fractionalPart.length;
  const zerosToAdd = Math.max(0, decimals - fractionalDigits);
  const rawAmount = wholePart + fractionalPart + "0".repeat(zerosToAdd);
  return rawAmount.replace(/^0+/, "") || "0";
}
export function useDefaultInitialPrice({
  currencies,
  skip
}) {
  const [price, setPrice] = useState();
  const currency0 = currencies[PositionField.TOKEN0];
  const currency1 = currencies[PositionField.TOKEN1];
  const { data: poolData, isLoading } = useQuery({
    queryKey: ["initial-pool-price", currency0?.chainId, currency0?.wrapped.address, currency1?.wrapped.address],
    queryFn: async () => {
      if (!currency0 || !currency1) return null;
      const token0Addr = currency0.wrapped.address.toLowerCase();
      const token1Addr = currency1.wrapped.address.toLowerCase();
      try {
        console.log("[useDefaultInitialPrice] Fetching from DexScreener...");
        const [response0, response1] = await Promise.all([
          fetch(`https://api.dexscreener.com/latest/dex/tokens/${token0Addr}`),
          fetch(`https://api.dexscreener.com/latest/dex/tokens/${token1Addr}`)
        ]);
        if (response0.ok && response1.ok) {
          const data0 = await response0.json();
          const data1 = await response1.json();
          if (data0.pairs && data0.pairs.length > 0) {
            const directPair = data0.pairs.find(
              (pair) => pair.baseToken.address.toLowerCase() === token0Addr && pair.quoteToken.address.toLowerCase() === token1Addr || pair.baseToken.address.toLowerCase() === token1Addr && pair.quoteToken.address.toLowerCase() === token0Addr
            );
            if (directPair && directPair.liquidity && directPair.liquidity.usd > 100) {
              console.log("[useDefaultInitialPrice] Found DexScreener pair:", directPair.pairAddress);
              return {
                source: "dexscreener",
                priceNative: parseFloat(directPair.priceNative),
                isToken0Base: directPair.baseToken.address.toLowerCase() === token0Addr
              };
            }
          }
          const COMMON_BASES = [
            "0x3439153eb7af838ad19d56e1571fbd09333c2809",
            // WETH Abstract Mainnet
            "0x84a71ccd554cc1b02749b35d22f684cc8ec987e1",
            // USDC.e Abstract Mainnet
            "0x9edcde0257f2386ce177c3a7fcdd97787f0d841d"
            // WETH Abstract Testnet
          ];
          for (const baseAddr of COMMON_BASES) {
            const pair0 = data0.pairs?.find(
              (p) => p.liquidity && p.liquidity.usd > 100 && (p.baseToken.address.toLowerCase() === baseAddr || p.quoteToken.address.toLowerCase() === baseAddr)
            );
            const pair1 = data1.pairs?.find(
              (p) => p.liquidity && p.liquidity.usd > 100 && (p.baseToken.address.toLowerCase() === baseAddr || p.quoteToken.address.toLowerCase() === baseAddr)
            );
            if (pair0 && pair1) {
              const price0InBase = pair0.baseToken.address.toLowerCase() === token0Addr ? parseFloat(pair0.priceNative) : 1 / parseFloat(pair0.priceNative);
              const price1InBase = pair1.baseToken.address.toLowerCase() === token1Addr ? parseFloat(pair1.priceNative) : 1 / parseFloat(pair1.priceNative);
              const crossRate = price0InBase / price1InBase;
              console.log("[useDefaultInitialPrice] Calculated DexScreener cross-rate:", crossRate);
              return {
                source: "dexscreener",
                priceNative: crossRate,
                isToken0Base: true
                // We calculated token1 per token0
              };
            }
          }
        }
      } catch (error) {
        console.log("[useDefaultInitialPrice] DexScreener fetch failed, falling back to subgraph:", error);
      }
      console.log("[useDefaultInitialPrice] Fetching from subgraph...");
      const subgraphs = getAbstractSubgraphs(currency0.chainId);
      const response = await fetch(subgraphs.v2, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          query: `{
            pairs(
              where: {
                or: [
                  { token0: "${token0Addr}", token1: "${token1Addr}" }
                  { token0: "${token1Addr}", token1: "${token0Addr}" }
                ]
              }
              first: 1
            ) {
              id
              token0 { id symbol decimals }
              token1 { id symbol decimals }
              reserve0
              reserve1
            }
          }`
        })
      });
      const data = await response.json();
      return data.data?.pairs?.[0] || null;
    },
    enabled: !!currency0 && !!currency1 && !skip,
    staleTime: 3e4
    // 30 seconds
  });
  useEffect(() => {
    if (!poolData || !currency0 || !currency1) {
      setPrice(void 0);
      return;
    }
    try {
      const token0 = currency0.wrapped;
      const token1 = currency1.wrapped;
      if ("source" in poolData && poolData.source === "dexscreener") {
        const { priceNative, isToken0Base } = poolData;
        if (isToken0Base) {
          const resultPrice2 = new Price(
            currency0,
            currency1,
            10 ** currency0.decimals,
            Math.floor(priceNative * 10 ** currency1.decimals)
          );
          console.log("[useDefaultInitialPrice] DexScreener price:", resultPrice2.toSignificant(6), `${resultPrice2.quoteCurrency.symbol} per ${resultPrice2.baseCurrency.symbol}`);
          setPrice(resultPrice2);
          return;
        } else {
          const invertedPrice = 1 / priceNative;
          const resultPrice2 = new Price(
            currency0,
            currency1,
            10 ** currency0.decimals,
            Math.floor(invertedPrice * 10 ** currency1.decimals)
          );
          console.log("[useDefaultInitialPrice] DexScreener price (inverted):", resultPrice2.toSignificant(6), `${resultPrice2.quoteCurrency.symbol} per ${resultPrice2.baseCurrency.symbol}`);
          setPrice(resultPrice2);
          return;
        }
      }
      const reserve0 = parseReserveToRaw(poolData.reserve0, parseInt(poolData.token0.decimals));
      const reserve1 = parseReserveToRaw(poolData.reserve1, parseInt(poolData.token1.decimals));
      if (reserve0 === "0" || reserve1 === "0") {
        setPrice(void 0);
        return;
      }
      const poolToken0Addr = poolData.token0.id.toLowerCase();
      const isToken0First = token0.address.toLowerCase() === poolToken0Addr;
      const amount0 = CurrencyAmount.fromRawAmount(
        isToken0First ? token0 : token1,
        isToken0First ? reserve0 : reserve1
      );
      const amount1 = CurrencyAmount.fromRawAmount(
        isToken0First ? token1 : token0,
        isToken0First ? reserve1 : reserve0
      );
      const pair = new Pair(amount0, amount1);
      const resultPrice = isToken0First ? pair.token0Price : pair.token1Price;
      console.log("[useDefaultInitialPrice] Subgraph reserves:");
      console.log("  Reserve0:", poolData.reserve0, poolData.token0.symbol);
      console.log("  Reserve1:", poolData.reserve1, poolData.token1.symbol);
      console.log("  Calculated price:", resultPrice.toSignificant(6), `${resultPrice.quoteCurrency.symbol} per ${resultPrice.baseCurrency.symbol}`);
      setPrice(resultPrice);
    } catch (error) {
      console.error("[useDefaultInitialPrice] Error calculating price:", error);
      setPrice(void 0);
    }
  }, [poolData, currency0, currency1]);
  useEffect(() => {
    setPrice(void 0);
  }, [currency0, currency1]);
  return { isLoading, price };
}
